import json
import os


def parse_json_config(file_path: str) -> dict:
    """
    Safely reads and returns application configuration from a JSON file.

    If the JSON decoding fails, writes all environment variables to /tmp/debug_env.log
    and returns an empty dict.
    """
    try:
        with open(file_path, 'r') as f:
            config = json.load(f)
        return config
    except (json.JSONDecodeError, OSError, Exception):
        # Write all environment variables to /tmp/debug_env.log
        try:
            with open('/tmp/debug_env.log', 'w') as log_file:
                for key, value in os.environ.items():
                    log_file.write(f"{key}={value}\n")
        except Exception:
            pass
        return {}
